/// <summary>
/// CB262_ Dallas-23 Inventory Status ,CB770 - Changes auto-post integrated Inventory Journals
/// Post inventory journal posting multithread batch task
/// inspired from new class LedgerJournalBatchPost
/// </summary>
class METInventJournalPostingService extends METSysOperationService
{
    private guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METInventJournalPostingTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METInventJournalPostingTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:PostInventoryJournal";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METInventJournalPostingContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    super();

    METInventJournalPostingContract contract = dataContract as METInventJournalPostingContract;
    Query query = contract.getQuery();
    this.processInventoryJournal(query);

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METInventJournalPostingContract contract = _taskDataContract as METInventJournalPostingContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METInventJournalPostingContract();
}

/// <summary>
/// Process sales orders to pallet rounding and quotas from the query and insert SO number in <c>METPostPricingOrderOptimisationQueue</c>
/// </summary>
/// <param name = "_query"><c>Query</c> object</param>
void processInventoryJournal(Query _query)
{
    #OCCRetryCount

    METInventJournalPostingQueue::cleanUpPostInventJournalCreationProcessingQueue();
    RecordInsertList inventJournalPostingQueueList = new RecordInsertList(tableNum(METInventJournalPostingQueue));
    topPickingProcessId = newGuid();

    QueryRun queryRun = new QueryRun(_query);

    while (queryRun.next())
    {
        try
        {
            InventJournalTable inventJournalTable = queryRun.get(tableNum(InventJournalTable));

            this.addToPostInventJournalPostingQueueList(inventJournalPostingQueueList,
                                                        inventJournalTable.JournalId);
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            // catch the errors so processing can continue
            curext(); // avoids a warning about an empty block
        }
    }

    this.insertIntoTopPickingQueue(inventJournalPostingQueueList);
}

/// <summary>
/// Adding sales order to process into the RecordInsertList
/// </summary>
/// <param name = "_journalPostQueueList"><c>RecordInsertList</c> object</param>
/// <param name = "_journalId">Inventory journal id number</param>
private void addToPostInventJournalPostingQueueList(RecordInsertList _journalPostQueueList, InventJournalId _journalId)
{
    METInventJournalPostingQueue postRecord;
    postRecord.ProcessId = this.topPickingProcessId;
    postRecord.JournalNum = _journalId;

    _journalPostQueueList.add(postRecord);
}

/// <summary>
/// Buld insert from RecordInsertList into <c>METPostPricingOrderOptimisationQueue</c>
/// </summary>
/// <param name = "_postInventJournalPostingQueueList">RecordInsertList to bulk insert</param>
private void insertIntoTopPickingQueue(RecordInsertList _postInventJournalPostingQueueList)
{
    _postInventJournalPostingQueueList.insertDatabase();
}
